class Solution:
    def targetIndices(self, nums: list[int], target: int) -> list[int]:
        count = 0
        lessThanTarget = 0
        for num in nums:
            if num == target:
                count += 1
            elif num < target:
                lessThanTarget += 1

        return [i for i in range(lessThanTarget, lessThanTarget + count)]
